const l = $input.item.json;

const budget  = {"Under ₦15m":5,"₦15m - ₦30m":12,"₦30m - ₦50m":19,"Above ₦50m":25};
const funds   = {"Ready (available now)":20,"Arranging (within 3 months)":12,"Not yet / unsure":3};
const english = {"Have a valid result":15,"Exempt / not required":12,"Booked a test":10,"Planning to take":6,"Not yet":0};
const source  = {"Referral":10,"Walk-in":9,"Website form":8,"Event":8,"Instagram":6,"WhatsApp":6,"Facebook":5};
const MONTHS  = {Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};

let intakePts = 5;
const m = String(l.intake || "").match(/([A-Za-z]{3})[a-z]*\s+(\d{4})/);
if (m && MONTHS[m[1]] !== undefined) {
  const months = (new Date(+m[2], MONTHS[m[1]], 1) - new Date()) / (1000*60*60*24*30);
  intakePts = months <= 6 ? 20 : months <= 12 ? 12 : 5;
}
const program = String(l.program_interest || "").trim();
const programPts = (program.length >= 4 && !/not sure/i.test(program)) ? 10 : 0;

const score = (budget[l.budget_range]||0) + (funds[l.funds_status]||0) + (english[l.english_test_status]||0)
            + intakePts + programPts + (source[l.source]||5);
const lead_score = Math.min(100, score);
const priority = lead_score >= 70 ? "Hot" : lead_score >= 40 ? "Warm" : "Cold";

return { json: { ...l, lead_score, priority } };

