const lead = $('Score lead').first().json;
const dest = String(lead.destination_country || '').toLowerCase();
let list = $input.all().map(i => i.json).filter(c => c.id);

// keep only active counselors who cover this lead's country
list = list.filter(c => c.is_active !== false &&
  String(c.coverage_area || '').toLowerCase().includes(dest));

// fewest active leads first
list.sort((a, b) => (a.active_lead_count || 0) - (b.active_lead_count || 0));
const c = list[0] || null;

return [{ json: {
  ...lead,
  counselor_id: c ? c.id : null,
  counselor_name: c ? c.name : "Unassigned",
  counselor_email: c ? c.email : null,
  counselor_telegram: c ? c.telegram_chat_id : null,
  counselor_count: c ? (c.active_lead_count || 0) : 0
}}];

const lead = $('Pick counselor').item.json;
let ai = {};
try {
  let raw = String($input.item.json.output || "");
  const s = raw.indexOf("{"), e = raw.lastIndexOf("}");
  ai = JSON.parse(raw.slice(s, e + 1));
} catch (err) { ai = {}; }

const first = String(lead.full_name || "there").split(" ")[0];
const nextDefault = lead.priority === "Hot"
  ? "Call within 2 hours and offer a consultation."
  : lead.priority === "Warm"
  ? "Message today and follow up within 24 hours."
: "Send an information message and call within 24 hours."; 
return { json: {
  ...lead,
  score_reason: ai.score_reason ||
    ("Scored " + lead.lead_score + "/100 from budget, funds, intake timing, English test, course clarity and source."),
  ai_next_action: ai.ai_next_action || nextDefault,
  ai_draft_message: ai.draft_message ||
    ("Hello " + first + ", thank you for your interest in studying in " + lead.destination_country +
     ". I'm " + lead.counselor_name + " from FemtorPath Consultancy. When is a good time for a quick call?")
}};

